#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

struct Cow {
    long long x, y;
    int id;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<Cow> east, north;
    for (int i = 0; i < n; i++) {
        char d;
        long long x, y;
        cin >> d >> x >> y;
        if (d == 'E') east.push_back({x, y, i});
        else north.push_back({x, y, i});
    }
    sort(east.begin(), east.end(), [](const Cow& a, const Cow& b) { return a.y < b.y; });
    sort(north.begin(), north.end(), [](const Cow& a, const Cow& b) { return a.x < b.x; });

    vector<bool> stopped(n, false);
    vector<int> blame(n, 0);

    for (const auto& e : east) {
        for (const auto& nc : north) {
            if (stopped[nc.id]) continue;
            if (e.x < nc.x && nc.y < e.y) {
                long long dx = nc.x - e.x;
                long long dy = e.y - nc.y;
                if (dx < dy) {
                    stopped[nc.id] = true;
                    blame[e.id] += 1 + blame[nc.id];
                } else if (dx > dy) {
                    stopped[e.id] = true;
                    blame[nc.id] += 1 + blame[e.id];
                    break;
                }
            }
        }
    }

    for (int i = 0; i < n; i++) cout << blame[i] << '\n';
    return 0;
}

