import java.io.*;
import java.util.*;

public class Main {
    static class Cow {
        long x, y;
        int id;
        Cow(long x, long y, int id) { this.x = x; this.y = y; this.id = id; }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        List<Cow> east = new ArrayList<>();
        List<Cow> north = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            char d = st.nextToken().charAt(0);
            long x = Long.parseLong(st.nextToken());
            long y = Long.parseLong(st.nextToken());
            if (d == 'E') east.add(new Cow(x, y, i));
            else north.add(new Cow(x, y, i));
        }
        east.sort(Comparator.comparingLong(c -> c.y));
        north.sort(Comparator.comparingLong(c -> c.x));

        boolean[] stopped = new boolean[n];
        int[] blame = new int[n];

        for (Cow e : east) {
            for (Cow nc : north) {
                if (stopped[nc.id]) continue;
                if (e.x < nc.x && nc.y < e.y) {
                    long dx = nc.x - e.x;
                    long dy = e.y - nc.y;
                    if (dx < dy) {
                        stopped[nc.id] = true;
                        blame[e.id] += 1 + blame[nc.id];
                    } else if (dx > dy) {
                        stopped[e.id] = true;
                        blame[nc.id] += 1 + blame[e.id];
                        break;
                    }
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(blame[i]).append('\n');
        System.out.print(sb);
    }
}

